#!/usr/bin/env node
// Fails when README.md or docs/**/*.md contain phrasing typical of AI-generated text.
// Code (fenced and inline) and quoted speech are skipped, so a page can still
// quote a bad phrase in order to discuss it.
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join, relative } from "node:path";

const root = process.cwd();

// Each rule: a pattern (case-insensitive) and the reason shown to the writer.
const RULES = [
  [/\bdelv(?:e|es|ed|ing)\b/, "\"delve\" — say \"look at\", \"cover\" or \"explain\""],
  [/\b(?:is|stands as|serves as) a testament to\b/, "\"a testament to\" — state the fact directly"],
  [/\bin today'?s (?:fast[- ]paced|ever[- ]changing|digital|modern) (?:world|landscape|age)\b/, "stock opener — cut it"],
  [/\bin the (?:ever[- ]evolving|fast[- ]paced|dynamic) (?:world|landscape|realm) of\b/, "stock opener — cut it"],
  [/\bseamless(?:ly)?\b/, "\"seamless\" — say what actually happens"],
  [/\b(?:navigate|navigating) the (?:complexities|landscape)\b/, "filler phrase"],
  [/\b(?:rich )?tapestry\b/, "\"tapestry\" — filler metaphor"],
  [/\b(?:unlock|unleash|harness) the (?:full )?(?:power|potential)\b/, "marketing filler"],
  [/\bembark on (?:a|your|the) journey\b/, "\"embark on a journey\" — filler metaphor"],
  [/\b(?:game[- ]changer|game[- ]changing)\b/, "hype word"],
  [/\bit(?:'s| is) (?:important|worth|crucial) (?:to note|noting)\b/, "filler — just say the thing"],
  [/\bplays? a (?:crucial|pivotal|vital) role\b/, "filler — say what it does"],
  [/\bthe future of [\w\s-]{1,40} (?:looks|is) bright\b/, "empty closer — cut it"],
  [/\blet me know if you have any (?:other |further )?questions\b/, "chatbot closer — cut it"],
  [/\b(?:i hope this helps|hope this helps)\b/, "chatbot closer — cut it"],
  [/\b(?:feel free to reach out|don'?t hesitate to (?:reach out|contact|ask))\b/, "chatbot closer — cut it"],
  [/\bas an ai(?: language model)?\b/, "AI self-reference"],
  [/\bcertainly!|\bgreat question\b/i, "chatbot phrasing"],
  [/\bin (?:conclusion|summary),/, "essay-style wrap-up — cut it"],
].map(([re, why]) => [new RegExp(re.source, "gi"), why]);

function markdownFiles() {
  const files = [];
  if (existsSync(join(root, "README.md"))) files.push(join(root, "README.md"));
  const docs = join(root, "docs");
  if (existsSync(docs)) {
    for (const f of readdirSync(docs, { recursive: true })) {
      if (String(f).endsWith(".md")) files.push(join(docs, String(f)));
    }
  }
  return files.sort();
}

// Blank out a match but keep its length, so reported columns stay correct.
const blank = (m) => " ".repeat(m.length);

function proseOnly(line) {
  return line
    .replace(/`[^`]*`/g, blank)            // inline code
    .replace(/"[^"\n]*"/g, blank)          // "straight quotes"
    .replace(/“[^”\n]*”/g, blank)          // “curly quotes”
    .replace(/„[^“”\n]*[“”]/g, blank)      // „German quotes“
    .replace(/«[^»\n]*»/g, blank)          // « French quotes »
    .replace(/<!--.*?-->/g, blank);        // HTML comments
}

let problems = 0;
for (const file of markdownFiles()) {
  const lines = readFileSync(file, "utf8").split("\n");
  let fence = null;
  lines.forEach((raw, i) => {
    const fenceMatch = raw.match(/^\s*(`{3,}|~{3,})/);
    if (fenceMatch) {
      if (!fence) fence = fenceMatch[1];
      else if (fenceMatch[1][0] === fence[0] && fenceMatch[1].length >= fence.length) fence = null;
      return;
    }
    if (fence) return;
    const text = proseOnly(raw);
    for (const [re, why] of RULES) {
      for (const m of text.matchAll(re)) {
        problems++;
        console.log(`${relative(root, file)}:${i + 1}:${m.index + 1}  "${m[0]}"  ${why}`);
      }
    }
  });
}

if (problems) {
  console.log(`\n${problems} AI-style phrase(s) found. Rewrite them in plain words.`);
  process.exit(1);
}
console.log("prose ok");
EOF
node scripts/lint-prose.mjs

